import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const c="/ascendc.github.io/pr/5487/assets/pipeline_wait.BfsbOQrZ.png",h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Reg矢量计算","link":"/api/SIMD-API/basic_api/reg_vector_compute/reg_vector_compute"},{"text":"同步控制","link":"/api/SIMD-API/basic_api/reg_vector_compute/sync_control/sync_control"},{"text":"LocalMemBar","link":"/api/SIMD-API/basic_api/reg_vector_compute/sync_control/LocalMemBar"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/reg_vector_compute/sync_control/LocalMemBar.md","filePath":"api/SIMD-API/basic_api/reg_vector_compute/sync_control/LocalMemBar.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),t={name:"api/SIMD-API/basic_api/reg_vector_compute/sync_control/LocalMemBar.md"};function e(d,s,r,i,o,_){return n(),p("div",null,[...s[0]||(s[0]=[l('<div><article class="markdown-body"><h1>LocalMemBar<span id="ZH-CN_TOPIC_0000002222134221"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/reg_compute/kernel_reg_compute_membar_intf.h&quot;</code>。</p><p>Reg矢量计算宏函数内不同流水线之间的同步指令。该同步指令指定src源流水线和dst目的流水线，如下图所示，目的流水线将等待源流水线上所有指令完成才进行执行。读写场景下，当读指令使用的寄存器和写指令使用的寄存器相同时，可以触发寄存器保序，指令将会按照代码顺序执行，不需要插入同步指令，而当使用的寄存器不同时，如果要确保读写指令顺序执行，则需要插入同步指令，写写场景同理。MemType用于标识不同的流水线类型，其具体取值与含义详见<a href="#table2_memtype">表 MemType取值说明</a>。</p><p><strong>图1</strong> 流水线等待示意图<span id="fig2635167165614"></span><br><img src="'+c+`" alt title="流水线等待示意图"></p><h2 id="函数原型">函数原型<span id="section620mcpsimp"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">MemType</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">MemType</span><span class="w"> </span><span class="n">dst</span><span class="o">&gt;</span><span class="w"> </span>
<span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">LocalMemBar</span><span class="p">()</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名称</th><th>描述</th></tr></thead><tbody><tr><td>src</td><td>源流水线，类型为MemType，具体参见<a href="#table2_memtype">表2 MemType取值说明</a>。</td></tr><tr><td>dst</td><td>目的流水线，类型为MemType，具体参见<a href="#table2_memtype">表2 MemType取值说明</a>。</td></tr></tbody></table><p><strong>表 2</strong> MemType取值说明<span id="table2_memtype"></span></p><table><thead><tr><th>MemType取值</th><th>含义</th></tr></thead><tbody><tr><td>VEC_STORE</td><td>SIMD_VF函数内矢量写UB流水线。<br>对应寄存器到UB的搬运指令，如StoreAlign、StoreUnAlign、Store。</td></tr><tr><td>VEC_LOAD</td><td>SIMD_VF函数内矢量读UB流水线。<br>对应UB到寄存器的搬运指令，如LoadAlign、LoadUnAlign、Load。</td></tr><tr><td>SCALAR_STORE</td><td>SIMD_VF函数内标量写UB流水线。<br>对应标量写入UB的指令。</td></tr><tr><td>SCALAR_LOAD</td><td>SIMD_VF函数内标量读UB流水线。<br>对应UB读取标量的指令。</td></tr><tr><td>VEC_ALL</td><td>SIMD_VF函数内所有矢量读写UB流水线。</td></tr><tr><td>SCALAR_ALL</td><td>SIMD_VF函数内所有标量读写UB流水线。</td></tr></tbody></table><p><strong>表3</strong> src和dst组合取值说明</p><table><thead><tr><th>src</th><th>dst</th></tr></thead><tbody><tr><td>MemType::VEC_STORE</td><td>MemType::VEC_LOAD</td></tr><tr><td>MemType::VEC_LOAD</td><td>MemType::VEC_STORE</td></tr><tr><td>MemType::VEC_STORE</td><td>MemType::VEC_STORE</td></tr><tr><td>MemType::VEC_STORE</td><td>MemType::SCALAR_LOAD</td></tr><tr><td>MemType::VEC_STORE</td><td>MemType::SCALAR_STORE</td></tr><tr><td>MemType::VEC_LOAD</td><td>MemType::SCALAR_STORE</td></tr><tr><td>MemType::SCALAR_STORE</td><td>MemType::VEC_LOAD</td></tr><tr><td>MemType::SCALAR_STORE</td><td>MemType::VEC_STORE</td></tr><tr><td>MemType::SCALAR_LOAD</td><td>MemType::VEC_STORE</td></tr><tr><td>MemType::VEC_ALL</td><td>MemType::VEC_ALL</td></tr><tr><td>MemType::VEC_ALL</td><td>MemType::SCALAR_ALL</td></tr><tr><td>MemType::SCALAR_ALL</td><td>MemType::VEC_ALL</td></tr></tbody></table><h2 id="返回值说明">返回值说明<span id="section640mcpsimp"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><p>读写依赖的场景下，如果读指令和写指令使用的寄存器相同，会触发寄存器保序，指令将会按照代码顺序执行，无需额外插入同步指令。</p><h2 id="调用示例">调用示例<span id="section642mcpsimp"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>如下示例中dstPtr和src0Ptr为同一个Unified Buffer（UB）地址，for循环的第二次迭代中读UB矢量搬运和第一次迭代中写UB矢量搬运操作了同一块UB地址空间，因此第二次循环中读UB矢量搬运需要等待第一次循环中写UB矢量搬运执行完成后才能执行，需要插入VEC_LOAD等待VEC_STORE的同步。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">AddVF</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">dstAddr</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">src0Addr</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">src1Addr</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcReg0</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcReg1</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstReg</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskReg</span><span class="w"> </span><span class="n">mask</span><span class="p">;</span><span class="w">   </span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">UpdateMask</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">(</span><span class="n">count</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LocalMemBar</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MemType</span><span class="o">::</span><span class="n">VEC_STORE</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MemType</span><span class="o">::</span><span class="n">VEC_LOAD</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadAlign</span><span class="p">(</span><span class="n">srcReg0</span><span class="p">,</span><span class="w"> </span><span class="n">src0Addr</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadAlign</span><span class="p">(</span><span class="n">srcReg1</span><span class="p">,</span><span class="w"> </span><span class="n">src1Addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Add</span><span class="p">(</span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">srcReg0</span><span class="p">,</span><span class="w"> </span><span class="n">srcReg1</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">StoreAlign</span><span class="p">(</span><span class="n">dstAddr</span><span class="p">,</span><span class="w"> </span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const m=a(t,[["render",e]]);export{h as __pageData,m as default};
